SELECT *
FROM policies
WHERE premium > 1000;

SELECT SUM(premium) AS total_premium
FROM policies
WHERE status = 'Active';

SELECT p.policy_holder_name, c.claim_amount, c.claim_date
FROM claims c
INNER JOIN policies p ON c.policy_id = p.policy_id;

SELECT status, AVG(premium) AS avg_premium
FROM policies
GROUP BY status;

SELECT MIN(premium) AS min_active_premium
FROM policies
WHERE status = 'Active';

SELECT status, COUNT(*) AS policy_count
FROM policies
GROUP BY status;

SELECT policy_id, start_date
FROM policies
WHERE start_date BETWEEN '2023-01-01' AND '2023-12-31';

SELECT *
FROM policies
ORDER BY premium DESC, policy_id;

SELECT p.policy_id, p.policy_holder_name, c.claim_amount
FROM policies p
LEFT JOIN claims c ON p.policy_id = c.policy_id;

SELECT c.claim_id, p.policy_holder_name, c.claim_amount
FROM policies p
RIGHT JOIN claims c ON p.policy_id = c.policy_id;

SELECT p.policy_id, c.claim_id, c.claim_amount
FROM policies p
FULL OUTER JOIN claims c ON p.policy_id = c.policy_id;

SELECT *
FROM policies
WHERE premium = (SELECT MAX(premium) FROM policies);

SELECT *
FROM policies
WHERE status IN ('Active', 'Pending');

SELECT *
FROM policies
WHERE policy_holder_name LIKE 'J%';

SELECT p1.policy_id AS policy1, p2.policy_id AS policy2, p1.premium
FROM policies p1
JOIN policies p2 ON p1.premium = p2.premium AND p1.policy_id < p2.policy_id;

SELECT customer_id,
  first_name || ' ' || last_name AS full_name
FROM customers;

SELECT policy_number,
  substr(policy_number, 1, 3) AS product_code
FROM policies;

SELECT policy_id,
  UPPER(policy_holder_name) AS name_upper
FROM policies;

SELECT policy_id,
  CAST(strftime('%Y', start_date) AS INTEGER) AS start_year
FROM policies;

SELECT policy_id,
  CAST(julianday(end_date) - julianday(start_date) AS INTEGER) AS days_duration
FROM policies;

SELECT policy_id,
  date(start_date, '+1 year') AS renewal_date
FROM policies;

SELECT claim_id,
  COALESCE(paid_amount, case_reserve, 0) AS claim_cost
FROM claims;

SELECT holder_id,
       COALESCE(mobile, work_phone, home_phone, 'No number') AS contact_number
FROM policyholders;

SELECT claim_id, reported_date
FROM claims
WHERE reported_date BETWEEN '2025-03-01' AND '2025-03-31';

SELECT MAX(salary) AS second_highest_salary
FROM underwriters
WHERE salary < (
  SELECT MAX(salary)
  FROM underwriters
);
